#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace DeliveryService.Mok.Editor{
[InitializeOnLoad]public static class DistrictInspect{
static DistrictInspect(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-district-inspect"))return;File.Delete("Temp/Mok-district-inspect");var s=SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");bool opened=!s.isLoaded;if(opened)s=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);try{var b=new StringBuilder();foreach(var n in new[]{"Environments/SM_Env_Road_01","Environments/SM_Env_Road_Bare_01","Environments/SM_Env_Sidewalk_01","Environments/SM_Env_Sidewalk_Panel_01","Buildings/SM_Bld_Apartment_01","Buildings/SM_Bld_Apartment_Stack_01","Buildings/SM_Bld_Shop_01","Buildings/SM_Bld_Shop_03","Buildings/SM_Bld_Shop_05"}){var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonCity/Prefabs/"+n+".prefab");var g=UnityEngine.Object.Instantiate(p);var rr=g.GetComponentsInChildren<Renderer>();var bounds=rr[0].bounds;foreach(var r in rr)bounds.Encapsulate(r.bounds);b.AppendLine(n+" bounds="+bounds+" materials="+string.Join(",",rr.SelectMany(r=>r.sharedMaterials).Distinct().Select(m=>m.name)));UnityEngine.Object.DestroyImmediate(g);}foreach(var g in s.GetRootGameObjects()){foreach(var c in g.GetComponentsInChildren<Collider>(true).Where(c=>c.GetComponentInParent<MotorcycleController>()!=null||c.GetComponent<PlayerMove>()!=null))b.AppendLine("BODY "+c.name+" layer="+c.gameObject.layer+" "+c.GetType().Name);foreach(var c in g.GetComponentsInChildren<Collider>(true).Where(c=>c.enabled&&!c.isTrigger&&c.bounds.Intersects(new Bounds(new Vector3(-165,2,-5),new Vector3(30,4,20)))))b.AppendLine("WEST "+c.name+" "+c.bounds);}File.WriteAllText("Temp/Mok-district-inspect.txt",b.ToString());}finally{if(opened)EditorSceneManager.CloseScene(s,true);}}
}}
#endif
